import{describe,it,expect}from"vitest";import fs from"fs";import path from"path";describe("sw.js Offline Region Download Manager",()=>{const e=fs.readFileSync(path.resolve(__dirname,"../../sw.js"),"utf8");it("defines a dedicated, unversioned cache for downloaded regions",()=>{expect(e).toContain("const CACHE_NAME_REGIONS = 'india-explorer-regions'")}),it("exempts the region cache from the activate handler's version cleanup",()=>{expect(e).toContain("isRegionCache"),expect(e).toContain("name === CACHE_NAME_REGIONS")}),it("handles DOWNLOAD_REGION, DELETE_REGION, GET_REGION_STATUS, and GET_ALL_REGION_STATUSES messages",()=>{expect(e).toContain("case 'DOWNLOAD_REGION'"),expect(e).toContain("case 'DELETE_REGION'"),expect(e).toContain("case 'GET_REGION_STATUS'"),expect(e).toContain("case 'GET_ALL_REGION_STATUSES'")}),it("persists region manifests in a dedicated IndexedDB database",()=>{expect(e).toContain("indexedDB.open('IndiaExplorerOfflineRegions'"),expect(e).toContain("db.createObjectStore('regions'")}),it("reports per-file download progress back to the requesting client",()=>{expect(e).toContain("REGION_DOWNLOAD_PROGRESS"),expect(e).toContain("REGION_DOWNLOAD_COMPLETE")}),it("deletes both cached files and the manifest record when a region is removed",()=>{expect(e).toContain("async function deleteRegion(regionId)"),expect(e).toContain("cache.delete(url)"),expect(e).toContain("deleteRegionRecord(regionId)")})});